import requests
from PIL import Image
import io

def task_func(url):
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")

    try:
        response = requests.get(url, timeout=5, verify=False)
        if not (200 <= response.status_code < 300):
            raise ValueError("Failed to fetch image: HTTP status code not successful.")

        image_data = io.BytesIO(response.content)
        img = Image.open(image_data)
        img.verify()

        image_data.seek(0)
        return Image.open(image_data)
    except (requests.RequestException, IOError, SyntaxError) as e:
        raise ValueError(f"Could not process image from URL: {e}")

from bs4 import BeautifulSoup
import requests

URL = "http://example.com"

def task_func(url=URL, from_encoding="cp1251", use_lxml=False):
