import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(f"{URL}{username}")
    response.raise_for_status()
    data = response.json()

    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = value

    return normalized_data

from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalData(Resource):
        def get(self):
            response = requests.get(api_url, verify=False)
            return response.json()

    api.add_resource(ExternalData, '/data')
    return app
